def semver_sort(versions):
    def parse_version(version):
        # Split off build metadata (after +)
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version

        # Split off pre-release (after first -)
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
        else:
            core = version_part
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
        else:
            prerelease_ids = None

        return (major, minor, patch, prerelease_ids)

    def prerelease_key(prerelease_ids):
        # None (no prerelease) sorts after any prerelease
        # So we return a tuple where the first element determines this
        if prerelease_ids is None:
            # Has no prerelease: sorts after any prerelease
            return (1,)
        else:
            # Has prerelease: sorts before no prerelease
            # Convert each identifier for comparison
            converted = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    # Numeric identifier: sort numerically, and before non-numeric
                    converted.append((0, int(identifier)))
                else:
                    # Non-numeric identifier: sort by ASCII, after numeric
                    converted.append((1, identifier))
            return (0, tuple(converted))

    # Create list of (sort_key, original_index, version_string)
    indexed_versions = []
    for i, version in enumerate(versions):
        parsed = parse_version(version)
        major, minor, patch, prerelease_ids = parsed
        sort_key = (major, minor, patch, prerelease_key(prerelease_ids))
        indexed_versions.append((sort_key, i, version))

    # Sort by key, then by original index for stability
    indexed_versions.sort(key=lambda x: (x[0], x[1]))

    # Extract sorted version strings
    return [v[2] for v in indexed_versions]

